+    workspace_pr: task.workspace_pr
+      ? { url: task.workspace_pr.url, status: task.workspace_pr.status }
+      : undefined,
+    blockedReason: task.is_blocked ? "blocked" : undefined,
+  };
+}
+
+export function adaptFeatureSummary(
