+  body: ImportWorkspaceRequest,
+  now: string,
+): LocalWorkspaceSummary {
+  const urlParts = body.repo_url.replace(/\.git$/, "").split("/");
+  const repoName = urlParts[urlParts.length - 1] ?? body.repo_url;
+  return {
+    workspaceId: detail.id,
